const map = { break_even: ["break_even", ["seuil-rentabilite"], "single_engine"], pricing: ["pricing", ["tarification"], "single_engine"], treasury: ["treasury", ["tresorerie"], "single_engine"], management_summary: ["management_summary", ["synthese-gestion"], "single_engine"], revenue_ledger: ["revenue_ledger", ["livre-recettes"], "single_engine"], pricing_then_break_even: ["pricing_then_break_even", ["tarification", "seuil-rentabilite"], "pricing_to_break_even"], ledger_then_summary: ["ledger_then_summary", ["livre-recettes", "synthese-gestion"], "qualified_transmission"] };
export function routeIntent(intent, requested_output_id) { const [id, engines, composition] = map[intent]; return [{ requested_output_id: requested_output_id ?? id, engines: engines, composition }]; }
